-- Australia Cloud Engineer profile.
update ingest.occupations_au
set shortage_rating = 5,
    on_csol = true,
    median_salary_aud = null,
    confidence = 'official-profile-osl-csol',
    source_name = 'ABS OSCA 2024 v1.0 + JSA 2025 OSL + reviewed CSOL correspondence',
    source_url = 'https://www.abs.gov.au/statistics/classifications/osca-occupation-standard-classification-australia/2024-version-1-0/browse-classification/2/27/273/2733/273331',
    last_verified = '2026-08-08',
    anzsco_v13 = '261313'
where anzsco_code = '273331' and occupation_en = 'Cloud Engineer';

update ingest.visa_occupation_status_au
set reviewed_at = now(), reviewer_note = 'Reviewed OSCA 273331 Cloud Engineer correspondence to legacy ANZSCO 261313 Software Engineer. The legal CSOL lists 261313 with ACS; Cloud Engineer is not listed there as a separate title.'
where osca_code = '273331' and anzsco_v13_code = '261313' and list_name = 'Core Skills Occupation List (CSOL)' and status = 'eligible';

values ('AU:cloud-engineer','AU','cloud-engineer','Cloud Engineer','OSCA','2024 v1.0','2733','AUD',false,'Australian Computer Society (ACS) — migration skills assessment under the applicable legacy ICT occupation; no statutory national occupational registration','https://www.acs.org.au/msa/information-for-applicants/occupations-anzsco-codes/information-technology.html','profile_ready','2026-08-08',now())
on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();

values ('AU:cloud-engineer','2026-05-01',null,null,null,null,1852,null,null,null,null,3392,'2026-05-01',-9.86,15.69,26.67,20,0,5,0,10,0,5,10,4,54,'career-opportunity-v1','provisional',jsonb_build_object('current_classification_scope','CampCareer maps Cloud Engineer exactly to OSCA 273331 Cloud Engineer. ABS defines the occupation around building, supporting, managing and maintaining cloud-based solutions and services, including deployment, configuration, automation, cloud applications, performance, security, compliance and cloud migration.','legacy_mapping','Cloud Engineer did not have a dedicated ANZSCO 2022 six-digit occupation. CampCareer uses the reviewed ABS OSCA correspondence already present in the Australian occupation model, which associates OSCA 273331 with legacy ANZSCO 261313 Software Engineer for migration-list continuity. This is not treated as proof that all legacy 261313 labour-market observations describe Cloud Engineers.','broader_anzsco_2613_context',jsonb_build_object('employment_total',203200,'median_weekly_earnings_aud',2537,'median_hourly_earnings_aud',67,'part_time_share_pct',6,'female_share_pct',21,'median_age',38,'average_full_time_hours',41,'scope','ANZSCO 2613 Software and Applications Programmers; broad legacy context only and not an exact Cloud Engineer series'),'vacancy_scope','The May 2026 IVI three-month-average value of 3392 and state vacancy values are published on broader legacy ANZSCO 2613. May 2025 was 3763, giving -9.86% year-on-year. Vacancy intensity is not scored because an exact current-OSCA Cloud Engineer employment denominator is unavailable, and the negative broader vacancy trend scores zero.','projection_scope','JSA Employment Projections for broader legacy ANZSCO 2613 are +15.69% from May 2025 to May 2030 and +26.67% to May 2035. These values receive only partial growth credit because ANZSCO 2613 contains several software occupations and is not an exact Cloud Engineer series.','shortage_note','The JSA 2025 Occupation Shortage List records current OSCA 273331 Cloud Engineer as Shortage nationally. The reviewed state source records shortage in ACT, NSW, QLD, SA, TAS, VIC and WA, while NT is not carried as a shortage row. National shortage therefore receives full shortage credit; regional rows preserve only verified ratings.','visa_basis','CampCareer production contains a reviewed CSOL correspondence from OSCA 273331 to legacy ANZSCO 261313 Software Engineer. The current legal CSOL lists ANZSCO 261313 with ACS rather than Cloud Engineer as a separate title. Visa scoring reflects that reviewed correspondence only; applicants must ensure their actual duties and nominated occupation meet current Home Affairs and ACS requirements.','registration_basis','There is no single statutory national occupational registration or licence to work as a Cloud Engineer in Australia. ACS migration skills assessment under an applicable ICT occupation is an immigration and professional-assessment process rather than a domestic licence to practise.','entry_level_basis','OSCA assigns Skill Level 1. Australian programs provide cloud-focused Bachelor and postgraduate study, but many Cloud Engineer roles expect prior software, systems, networking, Linux, infrastructure-as-code or platform experience plus practical AWS, Azure or Google Cloud skills. Entry-level credit is therefore moderated rather than treated as a universal graduate role.','entry_burden_basis','OSCA Skill Level 1 corresponds to a Bachelor degree or higher qualification, or at least five years of relevant experience. No additional statutory occupational licence applies.','employer_diversity_basis','Curated coverage across hyperscale cloud, software, telecommunications, banking and technology services; replace with posting-level unique-employer counts when available.','score_note','Conservative provisional score. The exact 2025 OSCA shortage signal receives full shortage credit and the reviewed migration correspondence retains visa credit. Exact Cloud Engineer employment, earnings and vacancy intensity are not inferred from broader legacy ANZSCO 2613, broader vacancies fell year on year, broader long-term growth receives partial credit, and entry access is moderated because many jobs expect production infrastructure experience.'),'2026-08-08')
on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;

values ('AU:cloud-engineer','273331','Cloud Engineer','ANZSCO','2022','261313',5,true,true,1,'https://www.abs.gov.au/statistics/classifications/osca-occupation-standard-classification-australia/2024-version-1-0/browse-classification/2/27/273/2733/273331','2026-08-08')
on conflict (profile_key,official_code) do update set official_title=excluded.official_title,legacy_code_system=excluded.legacy_code_system,legacy_code_version=excluded.legacy_code_version,legacy_code=excluded.legacy_code,shortage_rating=excluded.shortage_rating,visa_eligible=excluded.visa_eligible,included_in_rollup=excluded.included_in_rollup,sort_order=excluded.sort_order,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at;

on conflict (profile_key,region_code,as_of_date) do update set shortage_rating=excluded.shortage_rating,vacancy_count=excluded.vacancy_count,source_url=excluded.source_url;

on conflict (profile_key,link_type,url) do update set label=excluded.label,provider_type=excluded.provider_type,region_code=excluded.region_code,sort_order=excluded.sort_order,source_checked_at=excluded.source_checked_at;

